//! Tests for the committed Round 8 example golden.
//!
//! The golden reign reading of the standing example meet is
//! regenerated by the reign command itself, and these pins
//! fail if the example, the golden, or the reading drifts
//! away from the hand computed reign of the standing meet.

use std::fs;
use std::path::PathBuf;

use paceghost::cli::dispatch;
use paceghost::meet::{load_meet_file, meet_reign};
use paceghost::pytext::PText;

fn reader(bytes: &[u8]) -> Option<String> {
    let path = String::from_utf8_lossy(bytes).into_owned();
    let data = std::fs::read(path).ok()?;
    String::from_utf8(data).ok()
}

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

#[test]
fn test_the_example_reign_matches_the_golden_bytes() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_reign(&meet).expect("the example reign reads");
    let golden =
        fs::read_to_string(examples.join("meet-reign-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<&str> = golden.lines().collect();
    assert_eq!(lines, golden_lines);
    assert!(golden.ends_with('\n'));
}

#[test]
fn test_the_reign_command_prints_the_golden_reign() {
    let examples = examples_dir();
    let golden =
        fs::read_to_string(examples.join("meet-reign-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<String> = golden.lines().map(str::to_string).collect();
    let argv: Vec<PText> = vec![
        PText::from_text("reign"),
        PText::from_text(examples.join("meet.json").to_str().unwrap()),
    ];
    let outcome = dispatch(&argv, &reader);
    assert_eq!(outcome.code, 0);
    assert_eq!(outcome.stdout, golden_lines);
    assert!(outcome.stderr.is_empty());
}

#[test]
fn test_the_example_reign_closes_on_the_hand_counts() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_reign(&meet).expect("the example reign reads");
    // The hand counts of the standing meet, computed from the
    // one walk. Dawn fork holds after the last seven marks in
    // one unbroken spell, so the longest spell is dawn fork's
    // and the five spells name three holders.
    assert_eq!(
        lines[4],
        "spell, night fork, first mark at 900 seconds on the first day, last mark at 300 seconds on the second day, 5 marks"
    );
    assert_eq!(
        lines[5],
        "spell, dawn fork, first mark at 400 seconds on the second day, last mark at 600 seconds on the third day, 7 marks"
    );
    assert_eq!(
        lines.last().map(String::as_str),
        Some("reign counts, marks walked 16, spells 5, holders 3, longest spell 7 marks held by dawn fork")
    );
}
